using System;using System.Collections.Generic;using System.IO;using System.Linq;using System.Text.RegularExpressions;using System.Threading;using System.Web.Script.Serialization;using System.Windows.Media;
namespace Iris {
    public sealed class DiscordServerGroup {public string Id,Name;public DateTime ReadUtc;public List<DiscordChannelChoice> Channels=new List<DiscordChannelChoice>();}
    public sealed class DiscordNavigationCatalog {
        public int Format=1;public List<DiscordServerGroup> Servers=new List<DiscordServerGroup>();
        public static DiscordNavigationCatalog Read(string path){try{if(!File.Exists(path)||new FileInfo(path).Length>8*1024*1024)return new DiscordNavigationCatalog();var value=new JavaScriptSerializer{MaxJsonLength=8*1024*1024}.Deserialize<DiscordNavigationCatalog>(File.ReadAllText(path));if(value==null||value.Format!=1||value.Servers==null||value.Servers.Count>512)return new DiscordNavigationCatalog();value.Servers=value.Servers.Where(g=>g!=null&&(g.Id=="@me"||Regex.IsMatch(g.Id??"",@"^[0-9]{1,20}$"))&&g.Channels!=null).GroupBy(g=>g.Id).Select(g=>g.First()).ToList();foreach(var group in value.Servers){group.Name=Clean(group.Name,120);if(group.Name.Length==0)group.Name=group.Id=="@me"?L.T("Direktnachrichten"):"Server "+group.Id;group.Channels=group.Channels.Where(DiscordTextNavigation.Allowed).Where(c=>(c.Kind=="dm"?"@me":c.ServerId)==group.Id).GroupBy(c=>c.Url).Select(c=>c.First()).Take(512).ToList();foreach(var channel in group.Channels){channel.Name=Clean(channel.Name,120);channel.Category=Clean(channel.Category,80);channel.ServerName=Clean(channel.ServerName,120);}}return value;}catch{return new DiscordNavigationCatalog();}}
        public static string Clean(string name,int limit){name=(name??"").Trim();return name.Length<=limit?name:name.Substring(0,limit);}
        public void Merge(DiscordReply reply){if(reply.Code!="ok")return;var now=DateTime.UtcNow;foreach(var server in reply.Servers??new List<DiscordServerInfo>()){if(server==null||!Regex.IsMatch(server.Id??"",@"^[0-9]{1,20}$"))continue;Group(server.Id,Clean(server.Name,120)).ReadUtc=now;}foreach(var channel in reply.Channels.Where(DiscordTextNavigation.Allowed)){string id=channel.Kind=="dm"?"@me":channel.ServerId;var group=Group(id,id=="@me"?L.T("Direktnachrichten"):Clean(channel.ServerName,120));group.ReadUtc=now;var previous=group.Channels.FindIndex(c=>c.Url==channel.Url);channel.Name=Clean(channel.Name,120);channel.Category=Clean(channel.Category,80);if(previous>=0)group.Channels[previous]=channel;else if(group.Channels.Count<512)group.Channels.Add(channel);}Servers=Servers.OrderByDescending(g=>g.ReadUtc).Take(512).ToList();}
        DiscordServerGroup Group(string id,string name){var group=Servers.FirstOrDefault(g=>g.Id==id);if(group==null){group=new DiscordServerGroup{Id=id,Name=string.IsNullOrWhiteSpace(name)?"Server "+id:name};Servers.Add(group);}else if(!string.IsNullOrWhiteSpace(name))group.Name=name;return group;}
        public void Save(string path){var json=new JavaScriptSerializer{MaxJsonLength=8*1024*1024}.Serialize(this);if(json.Length>8*1024*1024)throw new InvalidDataException(L.T("Discord-Auswahl ist zu groß."));Directory.CreateDirectory(Path.GetDirectoryName(path));string temp=path+".tmp";File.WriteAllText(temp,json,System.Text.Encoding.UTF8);if(File.Exists(path))File.Replace(temp,path,null);else File.Move(temp,path);}
    }
    public sealed class DiscordNavigationView {public DiscordNavigationCatalog Catalog;public string Message;public Dictionary<string,ImageSource> Icons=new Dictionary<string,ImageSource>();}
    public static class DiscordNavigationReader {
        static readonly object gate=new object();
        public static DiscordNavigationView Load(string directory,DiscordReply reply,CancellationToken token){token.ThrowIfCancellationRequested();var view=new DiscordNavigationView();string path=Path.Combine(directory,"discord-navigation.json");lock(gate){token.ThrowIfCancellationRequested();view.Catalog=DiscordNavigationCatalog.Read(path);view.Catalog.Merge(reply);if(reply.Code=="ok"){token.ThrowIfCancellationRequested();try{view.Catalog.Save(path);}catch{view.Message=L.T("Die Serverliste konnte nicht gespeichert werden. Deine Kachelbelegung bleibt unabhängig davon.");}}}
            foreach(var group in view.Catalog.Servers.Where(g=>g.Id!="@me")){token.ThrowIfCancellationRequested();string icon=Path.Combine(directory,"DiscordServerIcons",group.Id+".png");try{if(File.Exists(icon)&&new FileInfo(icon).Length<=128*1024){var image=DiscordCachedIcons.Decode(File.ReadAllBytes(icon));if(image!=null)view.Icons[group.Id]=image;}}catch{}}
            var missing=(reply.Servers??new List<DiscordServerInfo>()).Where(s=>!view.Icons.ContainsKey(s.Id)).Select(s=>s.Id).ToArray();var found=DiscordCachedIcons.Read(missing,token);foreach(var item in found){token.ThrowIfCancellationRequested();view.Icons[item.Key]=item.Value;try{DiscordCachedIcons.SavePng(Path.Combine(directory,"DiscordServerIcons",item.Key+".png"),item.Value);}catch{}}
            if(string.IsNullOrEmpty(view.Message))view.Message=reply.Code=="ok"?L.T("Server aufklappen und Textkanal auswählen. Weitere Server in Discord öffnen und hier aktualisieren."):reply.Message+(view.Catalog.Servers.Count>0?L.T(" Gespeicherte Auswahl weiterhin verfügbar."):"");return view;}
    }
}
